def _parse_ym(ym):
    try:
        y, m = ym.split('-')
        yi, mi = int(y), int(m)
        if yi < 1970 or yi > 2200:
            raise ValueError('year out of range')
        if mi < 1 or mi > 12:
            raise ValueError('month out of range')
        return yi, mi
    except Exception:
        t = date.today()
        return t.year, t.month
